{
  "score": 4,
  "issues": [
    {
      "file": "emovec/extract.py",
      "lines": "23-27",
      "severity": "high",
      "description": "Tiny extraction still unconditionally requires external story manifest/files, so a clean checkout cannot run the advertised demo."
    },
    {
